select 'Indonesian Food Truck Association / Jakarta Food Truck', 'collective', 'ID', 'Jakarta', null, null, '{}'::text[], 'id', 'Asia/Jakarta', 'partners-3-lists-2026-11-16', 'not_now', 'medium', 'unverified', 'Not a network: @jktfoodtruck is a single food truck business, not an association (verification, 16 Nov 2026). Searches found no trace of the @jktfoodtruck handle, so it is unverified. Possible substitute: Komunitas Food Truck Jakarta (since 2016, Instagram @komunitas_foodtruck_jakarta per an alinear.id article snippet), which is a different group and not checked. Inactive: newest evidence 2016-12 (https://earthindonesiaforyou.blogspot.com/2016/12/food-trucks-boom-as-mouths-water-on.html) — nothing since 2024.', 'https://earthindonesiaforyou.blogspot.com/2016/12/food-trucks-boom-as-mouths-water-on.html', now(), false, 'email', null, null, null, '2016-12-01'::date, '40 trucks in Jakarta (Jakpat survey citing the association, undated); 70 trucks (2016 blog)'
where not exists (select 1 from public.partner_orgs p where (lower(p.name) = lower('Indonesian Food Truck Association / Jakarta Food Truck') and p.country_code is not distinct from 'ID'));
